import{_ as s,c as e,o as a,aj as t}from"./chunks/framework.Id7s26SP.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli/auth.md","filePath":"reference/cli/auth.md"}'),o={name:"reference/cli/auth.md"};function n(l,i,p,r,d,h){return a(),e("div",null,[...i[0]||(i[0]=[t('<h2 id="primitive-auth" tabindex="-1"><code>primitive auth</code> <a class="header-anchor" href="#primitive-auth" aria-label="Permalink to “primitive auth”">​</a></h2><p>Inspect and manage your admin sign-in sessions</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive auth [options]</span></span></code></pre></div><h3 id="primitive-auth-sessions" tabindex="-1"><code>primitive auth sessions</code> <a class="header-anchor" href="#primitive-auth-sessions" aria-label="Permalink to “primitive auth sessions”">​</a></h3><p>List and revoke admin sessions</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive auth sessions [options]</span></span></code></pre></div><h4 id="primitive-auth-sessions-list" tabindex="-1"><code>primitive auth sessions list</code> <a class="header-anchor" href="#primitive-auth-sessions-list" aria-label="Permalink to “primitive auth sessions list”">​</a></h4><p>List your admin sessions (any admin&#39;s with --admin-id, super-admin only)</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive auth sessions list [options]</span></span></code></pre></div><p>Options:</p><ul><li><code>--limit &lt;n&gt;</code> — Maximum rows to return (default 25, max 100)</li><li><code>--cursor &lt;cursor&gt;</code> — Pagination cursor from a previous page</li><li><code>--json</code> — Output as JSON</li></ul><h4 id="primitive-auth-sessions-revoke" tabindex="-1"><code>primitive auth sessions revoke</code> <a class="header-anchor" href="#primitive-auth-sessions-revoke" aria-label="Permalink to “primitive auth sessions revoke”">​</a></h4><p>Revoke an admin session: its refresh fails from now on</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive auth sessions revoke &lt;session-id&gt; [options]</span></span></code></pre></div><p>Arguments:</p><ul><li><code>&lt;session-id&gt;</code> — Session ID (from &#39;primitive auth sessions list&#39;)</li></ul><p>Options:</p><ul><li><code>-y, --yes</code> — Skip confirmation prompt</li><li><code>--json</code> — Output as JSON</li></ul><h4 id="primitive-auth-sessions-create" tabindex="-1"><code>primitive auth sessions create</code> <a class="header-anchor" href="#primitive-auth-sessions-create" aria-label="Permalink to “primitive auth sessions create”">​</a></h4><p>Create a CI session: a named token pinned to apps, approved in the browser and shown once</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive auth sessions create [options]</span></span></code></pre></div><p>Options:</p><ul><li><code>--name &lt;name&gt;</code> — A name for the session, shown in &#39;auth sessions list&#39; (required)</li><li><code>--scope &lt;list&gt;</code> — Scopes: read, write, data:read, data:write (never admin; required)</li><li><code>--app &lt;ids&gt;</code> — Pin the session to these app ids, comma-separated (required)</li><li><code>--ttl &lt;d&gt;</code> — Lifetime, such as 30d, 6mo or 1y (default 90d, at most 1y)</li><li><code>--json</code> — Output as JSON</li></ul><h3 id="primitive-auth-passkeys" tabindex="-1"><code>primitive auth passkeys</code> <a class="header-anchor" href="#primitive-auth-passkeys" aria-label="Permalink to “primitive auth passkeys”">​</a></h3><p><strong><code>Experimental</code></strong></p><p>List and delete the passkeys you sign in to the console with</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive auth passkeys [options]</span></span></code></pre></div><h4 id="primitive-auth-passkeys-list" tabindex="-1"><code>primitive auth passkeys list</code> <a class="header-anchor" href="#primitive-auth-passkeys-list" aria-label="Permalink to “primitive auth passkeys list”">​</a></h4><p><strong><code>Experimental</code></strong></p><p>List your passkeys, newest first</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive auth passkeys list [options]</span></span></code></pre></div><p>Options:</p><ul><li><code>--json</code> — Output as JSON</li></ul><h4 id="primitive-auth-passkeys-delete" tabindex="-1"><code>primitive auth passkeys delete</code> <a class="header-anchor" href="#primitive-auth-passkeys-delete" aria-label="Permalink to “primitive auth passkeys delete”">​</a></h4><p><strong><code>Experimental</code></strong></p><p>Delete one of your passkeys: it can no longer sign you in</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive auth passkeys delete &lt;passkey-id&gt; [options]</span></span></code></pre></div><p>Arguments:</p><ul><li><code>&lt;passkey-id&gt;</code> — Passkey ID (from &#39;primitive auth passkeys list&#39;)</li></ul><p>Options:</p><ul><li><code>-y, --yes</code> — Skip confirmation prompt</li><li><code>--json</code> — Output as JSON</li></ul>',41)])])}const k=s(o,[["render",n]]);export{u as __pageData,k as default};
